      await new Promise(r => setTimeout(r, 400));
      const submitBtns = Array.from(document.querySelectorAll('kat-button')).filter(b => b.getAttribute('label') === '提交');
      for (const sb of submitBtns) {
        sb.click();
        sb.shadowRoot?.querySelector('button')?.click();
      }
      await new Promise(r => setTimeout(r, 2500));
    }
  }
  return {
