  nativeInputValueSetter.call(qf, '304');
  qf.dispatchEvent(new Event('input', { bubbles: true }));
  qf.dispatchEvent(new Event('change', { bubbles: true }));
  qf.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  await new Promise(r => setTimeout(r, 2500));

  async function enableAndBudget(targetName, newBudget) {
    const matchCell = Array.from(document.querySelectorAll('[col-id="name"]')).find(c => c.innerText.includes(targetName));
    if (!matchCell) return { targetName, error: 'not found' };
    const rowIdx = matchCell.closest('[row-index]').getAttribute('row-index');
    const switchBtn = document.querySelector(`[row-index="${rowIdx}"] [col-id="state"] button[role="switch"]`);
    const beforeState = switchBtn?.getAttribute('aria-label');
    if (switchBtn && beforeState === '已暂停') {
      switchBtn.click();
      await new Promise(r => setTimeout(r, 1200));
    }
    const budgetCell = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`);
    const beforeBudget = budgetCell?.innerText.replace(/\n+/g, ' ').trim();
    if (newBudget && !beforeBudget.includes(`US$${newBudget}.00`)) {
      budgetCell.querySelector('button').click();
      await new Promise(r => setTimeout(r, 600));
      const input = document.querySelector('input[aria-label="enter amount in US$"]');
      if (input) {
        nativeInputValueSetter.call(input, String(newBudget));
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        await new Promise(r => setTimeout(r, 300));
        const saveBtn = document.getElementById('campaignOverviewAllCampaigns:cell-budget:save') || Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === '保存');
        if (saveBtn) saveBtn.click();
        await new Promise(r => setTimeout(r, 1500));
      }
    }
    const afterState = document.querySelector(`[row-index="${rowIdx}"] [col-id="state"] button[role="switch"]`)?.getAttribute('aria-label');
    const afterStatus = document.querySelector(`[row-index="${rowIdx}"] [col-id="status"]`)?.innerText.trim();
    const afterBudget = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`)?.innerText.replace(/\n+/g, ' ').trim();
    return { targetName, rowIdx, beforeState, afterState, afterStatus, beforeBudget, afterBudget };
  }

  const r1 = await enableAndBudget('SP_304满胶400_KW EXACT 1_20250610', 4);
  const r2 = await enableAndBudget('SP_304满胶_AUTO CLOSE_20250610', 3);
  const asinCampLink = Array.from(document.querySelectorAll('[col-id="name"] a')).find(a => a.innerText.includes('SP_304满胶_ASIN 竞_20250724'))?.href;
  return { r1, r2, asinCampLink };
}","pageId":8,"toolSummary":"Enable 2 paused 304 campaigns and set budgets in Campaign Manager","waitForStableDom":true}

