tool_calls.arguments_json:
{"function":"async () => {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  function setKatInput(katEl, val) {
    if (!katEl) return;
    katEl.value = String(val);
    katEl.setAttribute('value', String(val));
    const inner = katEl.shadowRoot?.querySelector('input');
    if (inner) {
      nativeInputValueSetter.call(inner, String(val));
      inner.dispatchEvent(new Event('input', { bubbles: true, composed: true }));
      inner.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    }
    katEl.dispatchEvent(new CustomEvent('input', { detail: { value: String(val) }, bubbles: true, composed: true }));
    katEl.dispatchEvent(new CustomEvent('change', { detail: { value: String(val) }, bubbles: true, composed: true }));
  }

  async function configureB2B(asin, b2bPrice) {
    const b2bContainers = Array.from(document.querySelectorAll('[data-test-id="business-price"]'));
    const targetContainer = b2bContainers.find(c => {
      let p = c;
      while (p && p !== document.body) {
        if (p.innerText && p.innerText.includes(asin) && p.innerText.split('ASIN').length === 2) return true;
        p = p.parentElement;
      }
      return false;
    });
    if (!targetContainer) return { asin, error: 'container not found' };
    const beforeRowText = targetContainer.innerText.replace(/\s+/g, ' ').trim();
    const link = targetContainer.querySelector('a');
    if (!link) return { asin, beforeRowText, error: 'link not found' };
    link.click();
    await new Promise(r => setTimeout(r, 1500));

    const b2bPanel = document.querySelector('[data-f1-component="solar/B2BInsightsActionPanel"]');
    if (!b2bPanel || !(b2bPanel.innerText || b2bPanel.textContent || '').includes(asin)) {
      return { asin, error: 'panel did not load asin' };
    }

    let katInputs = Array.from(b2bPanel.querySelectorAll('kat-input'));
    const beforeInputs = katInputs.map(k => k.value);
    // If only 1 tier exists (3 kat-inputs: [b2bPrice, qty1, pct1]), click "添加更多阈值" to add 2nd tier
    if (katInputs.length === 3) {
      const addTierLink = Array.from(b2bPanel.querySelectorAll('kat-link')).find(l => (l.getAttribute('label') || l.innerText || l.textContent || '').includes('添加更多阈值'));
      if (addTierLink) {
        addTierLink.click();
        addTierLink.shadowRoot?.querySelector('a, button')?.click();
        await new Promise(r => setTimeout(r, 600));
        katInputs = Array.from(b2bPanel.querySelectorAll('kat-input'));
      }
    }

    setKatInput(katInputs[0], b2bPrice);
