{"function":"async () => {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  function setKatInput(katEl, val) {
    if (!katEl) return;
    katEl.value = String(val);
    katEl.setAttribute('value', String(val));
    const inner = katEl.shadowRoot?.querySelector('input');
    if (inner) {
      inner.focus();
      nativeInputValueSetter.call(inner, String(val));
      inner.dispatchEvent(new Event('input', { bubbles: true, composed: true }));
      inner.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
      inner.blur();
    }
    katEl.dispatchEvent(new CustomEvent('input', { detail: { value: String(val) }, bubbles: true, composed: true }));
    katEl.dispatchEvent(new CustomEvent('change', { detail: { value: String(val) }, bubbles: true, composed: true }));
  }

  const targets = [
    { asin: 'B07JVSYNYV', price: '14.49' },
    { asin: 'B07J6Q5TTR', price: '12.49' },
    { asin: 'B07Z2555TN', price: '15.49' },
    { asin: 'B073VPHSJ9', price: '13.49' },
    { asin: 'B07DLM2QP1', price: '13.49' },
    { asin: 'B07T42DXZ1', price: '14.49' },
    { asin: 'B00SMEE5HU', price: '13.49' },
    { asin: 'B073VPFBL6', price: '14.49' }
  ];

  const results = [];
  for (const t of targets) {
    const b2bContainers = Array.from(document.querySelectorAll('[data-test-id="business-price"]'));
    const targetContainer = b2bContainers.find(c => {
      let p = c;
      while (p && p !== document.body) {
        if (p.innerText && p.innerText.includes(t.asin) && p.innerText.split('ASIN').length === 2) return true;
        p = p.parentElement;
      }
      return false;
    });
    if (!targetContainer) {
      results.push({ asin: t.asin, error: 'container not found' });
      continue;
    }
    const link = targetContainer.querySelector('a');
    link.click();
    await new Promise(r => setTimeout(r, 1200));

    const b2bPanel = document.querySelector('[data-f1-component="solar/B2BInsightsActionPanel"]');
    if (!b2bPanel || !(b2bPanel.innerText || b2bPanel.textContent || '').includes(t.asin)) {
      results.push({ asin: t.asin, error: 'panel not loaded' });
      continue;
    }
    const katInputs = Array.from(b2bPanel.querySelectorAll('kat-input'));
    const beforeInputs = katInputs.map(k => k.value);
    setKatInput(katInputs[0], t.price);
    if (katInputs.length >= 3) {
      setKatInput(katInputs[1], '2');
      setKatInput(katInputs[2], '3');
    }
    await new Promise(r => setTimeout(r, 400));
    const saveKatBtn = Array.from(b2bPanel.querySelectorAll('kat-button')).find(b => b.getAttribute('label') === '保存更改');
    const saveDisabled = saveKatBtn?.disabled || saveKatBtn?.hasAttribute('disabled');
    if (saveKatBtn && !saveDisabled) {
      saveKatBtn.click();
      saveKatBtn.shadowRoot?.querySelector('button')?.click();
      await new Promise(r => setTimeout(r, 1800));
    }
    const afterText = (b2bPanel.innerText || b2bPanel.textContent || '').replace(/\s+/g, ' ');
    results.push({
      asin: t.asin,
      beforeInputs,
      afterInputs: Array.from(b2bPanel.querySelectorAll('kat-input')).map(k => k.value),
      saveDisabled,
      saved: afterText.includes('对您的库存所做的更改已保存')
    });
  }
  return results;
}","pageId":1,"toolSummary":"Configure B2B prices on all 8 in-stock Page 2 items","waitForStableDom":true}

